.sw{--sw-ink:#172b4d;--sw-muted:#63748b;--sw-line:#e0e7ef;--sw-blue:#2558c8;color:var(--sw-ink);max-width:1240px;margin:0 auto;padding:24px 12px 48px;font-size:14px;line-height:1.55}.sw *{box-sizing:border-box}.sw [hidden]{display:none!important}.sw h1{font-size:28px;line-height:1.2;font-weight:700;margin:5px 0 8px;letter-spacing:-.6px}.sw h2{font-size:17px;font-weight:650;margin:0 0 14px}.sw h3{font-size:15px;font-weight:650;margin:0 0 8px}.sw p{margin:0 0 12px}.sw a{color:var(--sw-blue);text-decoration:none}.sw a:hover{text-decoration:underline}.sw .sw-muted{color:var(--sw-muted)}.sw .sw-eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:1.3px;font-weight:700;color:var(--sw-muted)}.sw-head{display:flex;gap:20px;align-items:center;justify-content:space-between;margin-bottom:24px}.sw-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.sw .sw-btn{display:inline-flex;align-items:center;justify-content:center;border:1px solid #ccd7e5;border-radius:8px;background:#fff;color:var(--sw-ink);padding:9px 15px;min-height:42px;font-weight:600;font-size:13px;cursor:pointer;text-decoration:none;white-space:normal}.sw .sw-btn:hover{background:#f3f6fb}.sw .sw-primary{background:var(--sw-blue);border-color:var(--sw-blue);color:#fff}.sw .sw-primary:hover{background:#1f47a4}.sw .sw-danger{color:#a32b35}.sw .sw-small{font-size:12px;padding:5px 10px;min-height:34px}.sw-panel{background:#fff;border:1px solid var(--sw-line);border-radius:12px;padding:22px;margin-bottom:18px;min-width:0}.sw-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px}.sw-metric{padding:16px 20px;border:1px solid var(--sw-line);border-radius:11px;background:#fff}.sw-metric strong{font-size:26px;display:block;font-weight:650}.sw .sw-overdue{color:#ad3944}.sw-tabs{display:flex;gap:24px;border-bottom:1px solid var(--sw-line);margin-bottom:18px;flex-wrap:wrap}.sw-tabs a{padding:12px 0;color:var(--sw-muted);font-weight:600;border-bottom:3px solid transparent}.sw-tabs a[aria-current=page]{color:var(--sw-blue);border-color:var(--sw-blue)}.sw-filters{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin-bottom:20px}.sw-field{display:flex;flex-direction:column;gap:5px;min-width:0}.sw label{font-size:12px;font-weight:650}.sw input:not([type=checkbox]):not([type=hidden]),.sw select,.sw textarea{width:100%;border:1px solid #cbd6e3;background:#fff;border-radius:7px;padding:10px 11px;font-size:14px;line-height:1.4;color:var(--sw-ink);min-height:42px;max-width:100%}.sw input:focus,.sw textarea:focus,.sw select:focus,.sw a:focus-visible,.sw button:focus-visible,.sw summary:focus-visible{outline:3px solid #b3cdf9;outline-offset:2px}.sw textarea{resize:vertical}.sw input[type=checkbox]{width:17px;height:17px;vertical-align:middle}.sw-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(270px,1fr);gap:22px}.sw-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.sw-full{grid-column:1/-1}.sw-list{display:grid;gap:0}.sw-row{padding:16px 0;border-bottom:1px solid var(--sw-line);display:flex;align-items:center;justify-content:space-between;gap:18px;min-width:0}.sw-row:last-child{border-bottom:0}.sw-row>div{min-width:0}.sw-row strong,.sw-row a,.sw-wrap{overflow-wrap:anywhere}.sw-meta{font-size:12px;color:var(--sw-muted);margin-top:5px}.sw-badge{display:inline-block;border-radius:5px;padding:3px 8px;background:#eef3fa;color:#49617e;font-size:11px;font-weight:700;text-transform:capitalize;white-space:nowrap}.sw-badge[data-status=accepted],.sw-badge[data-status=won],.sw-badge[data-status=converted]{background:#e9f6ef;color:#22704a}.sw-badge[data-status=sent],.sw-badge[data-status=quoted]{background:#eaf0ff;color:#315dba}.sw-badge[data-status=lost],.sw-badge[data-status=declined],.sw-badge[data-status=expired]{background:#fceeee;color:#a43d46}.sw-empty{text-align:center;padding:50px 20px}.sw-stage{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;list-style:none;padding:0;margin:0 0 22px}.sw-stage li{padding:10px 8px;b