.sw-head{margin:12px 0 18px}.sw-panel{padding:18px;margin-bottom:14px}.sw-metrics{gap:12px;margin-bottom:18px}.sw-metric{padding:10px 16px}.sw-metric strong{display:inline;margin-right:12px;font-size:23px}.sw-guide{padding:8px 0;color:var(--sw-muted)}.sw-stage{grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:14px}.sw-capture{max-width:920px}.sw-capture .sw-panel{max-width:none}.sw-panel>details:only-child{border:0;margin:0;padding:0}.sw details:not([open])>summary{margin-bottom:0}.sw-recipient>summary{display:list-item}.sw-recipient>summary .sw-meta{display:block}.sw-line-fields{grid-template-columns:minmax(160px,2fr) minmax(55px,.6fr) minmax(75px,1fr) minmax(75px,1fr) minmax(95px,1fr);gap:8px}.sw-line-card{padding:12px;margin-bottom:10px}.sw-sticky-summary{position:sticky;top:20px}.sw-editor-actions{display:grid;gap:8px}.sw-editor .sw-totals{max-width:none;margin:18px 0}.sw-editor .sw-btn,.sw-follow-up .sw-btn{min-height:42px}.sw-share-confirm{border-top:1px solid var(--sw-line);padding-top:12px;margin-top:12px}.sw-share-confirm button{margin-top:10px}.sw-follow-up>details{margin-top:8px;padding-top:10px}.sw-document-only{max-width:960px;margin:auto}.sw-review{width:min(960px,calc(100vw - 24px));max-height:92vh;border:1px solid var(--sw-line);border-radius:14px;padding:0;color:var(--sw-ink);margin:auto;overflow:auto}.sw-review::backdrop{background:rgba(17,32,55,.55)}.sw-review-head,.sw-review-footer{padding:16px 20px;background:#fff;display:flex;gap:16px;justify-content:space-between;align-items:center}.sw-review-head{border-bottom:1px solid var(--sw-line)}.sw-review-footer{position:sticky;bottom:0;border-top:1px solid var(--sw-line)}.sw-review>.sw-panel{border:0;margin:0;border-radius:0}.sw-review-footer p{margin:0;max-width:500px}.sw-logo{max-width:140px;max-height:56px;object-fit:contain;margin-bottom:10px}
